#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>
// Persistent fused LayerNorm kernel. This optimization replaces the single
// grid-wide software barrier with fine-grained per-row completion counters
// and release flags. Blocks still run one fused persistent kernel and are
// capped at the co-resident grid size, but a slice can be normalized as
// soon as all slices for its row have been reduced instead of waiting for
// every row in the batch. That keeps the just-reduced row slices hotter in
// L2 and removes the global all-rows drain point between phases.
__global__ void layernorm_fused_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    double* __restrict__ rowsum,
    double* __restrict__ rowsumsq,
    unsigned int* __restrict__ rowcount,
    unsigned int* __restrict__ rowready,
    float* __restrict__ y,
    const long long N,
    const long long items,
    const long long slices,
    const long long slice_len,
    const float eps) {
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int nwarps = (nthreads + 31) >> 5;
  const bool vec_ok = ((N & 3LL) == 0LL);
  __shared__ double ssum[32];
  __shared__ double ssq[32];
  // Phase 1: per-slice partial sums in double precision, atomically
  // accumulated into per-row totals. After the atomic accumulation for a
  // slice, count that slice; the last slice of a row releases that row.
  for (long long item = blockIdx.x; item < items; item += gridDim.x) {
    const long long row = item / slices;
    const long long slice = item - row * slices;
    const long long start = slice * slice_len;
    long long end = start + slice_len;
    if (end > N) end = N;
    double sum = 0.0;
    double sumsq = 0.0;
    if (start < end) {
      const float* xrow = x + row * N;
      if (vec_ok) {
        // N % 4 == 0 and slice_len % 4 == 0, so start/end are 16B aligned.
        const float4* x4 = reinterpret_cast<const float4*>(xrow);
        const long long vbegin = start >> 2;
        const long long vend = end >> 2;
        for (long long i = vbegin + tid; i < vend; i += nthreads) {
          const float4 v = x4[i];
          sum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
          sumsq += (double)v.x * (double)v.x + (double)v.y * (double)v.y +
                   (double)v.z * (double)v.z + (double)v.w * (double)v.w;
        }
      } else {
        for (long long i = start + tid; i < end; i += nthreads) {
          const double v = (double)xrow[i];
          sum += v;
          sumsq += v * v;
        }
      }
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum += __shfl_down_sync(0xffffffffu, sum, offset);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
    }
    if (lane == 0) {
      ssum[warp] = sum;
      ssq[warp] = sumsq;
    }
    __syncthreads();
    if (warp == 0) {
      double tsum = (lane < nwarps) ? ssum[lane] : 0.0;
      double tsq = (lane < nwarps) ? ssq[lane] : 0.0;
      for (int offset = 16; offset > 0; offset >>= 1) {
        tsum += __shfl_down_sync(0xffffffffu, tsum, offset);
        tsq += __shfl_down_sync(0xffffffffu, tsq, offset);
      }
      if (lane == 0) {
        atomicAdd(&rowsum[row], tsum);
        atomicAdd(&rowsumsq[row], tsq);
        __threadfence();
        const unsigned int done = atomicAdd(&rowcount[row], 1u) + 1u;
        if (done == (unsigned int)slices) {
          __threadfence();
          atomicExch(&rowready[row], 1u);
        }
      }
    }
    __syncthreads();
  }
  // Phase 2: normalize the same work items. Wait only for the item's row,
  // not for the whole grid; the co-resident grid cap still guarantees that
  // any unfinished contributor is resident and able to make progress.
