    const long long row = item / slices;
    const long long slice = item - row * slices;
    const long long start = slice * slice_len;
    long long end = start + slice_len;
    if (end > N) end = N;
    if (start >= end) continue;
    if (tid == 0) {
      while (atomicAdd(&rowready[row], 0u) == 0u) {
      }
      __threadfence();
    }
    __syncthreads();
    const double mean = rowsum[row] / (double)N;
    double var = rowsumsq[row] / (double)N - mean * mean;
    if (var < 0.0) var = 0.0;
    const float meanf = (float)mean;
    const float rstd = rsqrtf((float)var + eps);
    const float* xrow = x + row * N;
    float* yrow = y + row * N;
