torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");
  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  auto bc = bias.contiguous();
  const long long N = (long long)wc.numel();
  TORCH_CHECK(N > 0, "normalized_shape numel must be positive");
  TORCH_CHECK(xc.numel() % N == 0, "input trailing dims must match normalized_shape");
  const long long rows = (long long)xc.numel() / N;
  auto y = at::empty_like(xc);
  if (rows == 0) return y;
  auto stream = at::cuda::getCurrentCUDAStream();
  const int num_sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  const int threads = 256;
  int blocks_per_sm = 0;
  C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(
      &blocks_per_sm, layernorm_fused_kernel, threads, 0));
  if (blocks_per_sm < 1) blocks_per_sm = 1;
  const long long maxblocks = (long long)num_sms * (long long)blocks_per_sm;
  long long slices = (maxblocks + rows - 1LL) / rows;
  long long slice_len = (N + slices - 1LL) / slices;
  slice_len = (slice_len + 3LL) & ~3LL;  // keep 16B alignment of slice starts
  slices = (N + slice_len - 1LL) / slice_len;
  if (slices < 1) slices = 1;
  const long long items = rows * slices;
  long long grid = items < maxblocks ? items : maxblocks;
  if (grid < 1LL) grid = 1LL;
  // One fused zero-initialized allocation:
  // [rowsum | rowsumsq | rowcount(uint in 8B slots) | rowready(uint in 8B slots)].
  auto stats = at::zeros({4 * rows}, xc.options().dtype(at::kDouble));
  double* stats_ptr = stats.data_ptr<double>();
  double* rowsum = stats_ptr;
  double* rowsumsq = stats_ptr + rows;
  unsigned int* rowcount = reinterpret_cast<unsigned int*>(stats_ptr + 2 * rows);
  unsigned int* rowready = reinterpret_cast<unsigned int*>(stats_ptr + 3 * rows);
  layernorm_fused_kernel<<<(unsigned int)grid, threads, 0, stream>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bc.data_ptr<float>(),
      rowsum,
      rowsumsq,
      rowcount,
      rowready,
      y.data_ptr<float>(),
      N,
      items,
      slices,
      slice_len,
      (float)eps);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""
